# Typography of new editorial text, without touching IDs, dates, paths or legacy sections.
def tidy(s):
 s=re.sub(r'([А-ЯЁа-яё])(\d)',r'\1 \2',s);s=re.sub(r'(\d)([А-ЯЁа-яё])',r'\1 \2',s)
 s=re.sub(r'([A-Za-z])([А-ЯЁа-яё])',r'\1 \2',s);s=re.sub(r'([А-ЯЁа-яё])([A-Za-z])',r'\1 \2',s)
 pairs={'всвоей':'в своей','вэтом':'в этом','полнаяцена':'полная цена','длязаписи':'для записи','вплане':'в плане','радигалочки':'ради галочки','Новыйпитч':'Новый питч','тыс.порог':'тыс. порог','тыс.не':'тыс. не','оригиналов:2':'оригиналов: 2','1YouTube':'1 YouTube','своейScout':'своей Scout','послепроверки':'после проверки','невыдумывать':'не выдумывать','несуммируются':'не суммируются','непереписывать':'не переписывать','впервой':'в первой','поосновному':'по основному','подэтим':'под этим','доэтого':'до этого','Рилссериал':'Рилс-сериал','вчате':'в чате','отимени':'от имени','сырымедиа':'сырые медиа','неснятые':'не снятые'}
 for a,b in pairs.items():s=s.replace(a,b)
 return s
