for f in (P/'content-plan/handoffs/2026-v3').glob('*.md'):f.write_text(tidy(f.read_text()))
f=P/'departments/scout/jobs/V-202611-GEN-02/00-brief.md';f.write_text(tidy(f.read_text()))
for month in ['2026-11','2026-12']:
 f=P/'content-plan'/f'{month}.md';s=f.read_text();a=s.index('<!-- PUBLICATION_V3_START -->');b=s.index('<!-- PUBLICATION_V3_END -->')+len('<!-- PUBLICATION_V3_END -->');f.write_text(s[:a]+tidy(s[a:b])+s[b:])
p['report_markdown']=(O/'vernatun_publication_plan_2026.md').read_text()
(P/'content-plan/exports/publication-plan-2026-v3.json').write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
