payload=json.dumps(p,ensure_ascii=False).replace('</','<\\/')
weekbars=''.join(f'''<button class="weekbar" data-week="{w['week']}" aria-label="Неделя {w['week']}: {w['upper']} верхних и {w['lower']} нижних материалов"><span>Н{w['week']}</span><div class="bar"><i style="width:{w['upper']/w['total']*100}%"></i><b style="width:{w['lower']/w['total']*100}%"></b></div><small>{w['upper']} / {w['lower']}</small></button>''' for w in p['weeks'])
weekrows=''.join(f"<tr><td>Н{w['week']}</td><td>{w['start'][8:]}.{w['start'][5:7]} — {w['end'][8:]}.{w['end'][5:7]}</td><td>{w['formats'].get('REL',0)}</td><td>{w['formats'].get('CAR',0)}</td><td>{w['formats'].get('ART',0)}</td><td>{w['formats'].get('YTB',0)}</td><td>{w['upper']} / {w['lower']}</td><td>{w['total']}</td></tr>" for w in p['weeks'])
sourcecards=''.join(f"<article class='source'><p class='overline'>{e(s['id'])} · проверено 11.11</p><h3><a href='{e(s['url'])}' target='_blank' rel='noreferrer'>{e(s['name'])} ↗</a></h3><p>{e(s['finding'])}</p><p><b>Берём в работу:</b> {e(s['lesson'])}</p><small>{e(s['access'])}</small></article>" for s in p['sources'])
